#!/usr/bin/env python3
"""migrate_dual_metric.py -- DUAL-METRIC-V1 Phase 1 (2026-07-07). Idempotent.

Migre le pipeline vers la metrique duale (arcmin + metres transverses):
  1. tools/common.py: residual_dual() + cam_rms_dual() + find_fossils dual
     (fossile = ang>15' ET gap>3m; no-proj condamne d'office)
  2. tools/audit/rms_snapshot.py: median_m par cam/zone/global (remplace)
  3. tools/compute_confidence_tiers.py: annotation median_res_m + rapport
     des cams punies par l'arcmin (REGLES DE TIER INCHANGEES — Phase 2)
  4. tools/ci_healthcheck.py: print dual + baseline metres (tolerante si
     baseline ancienne sans metres)

Genese: "mes markings sont bons dans 99% des cas" — verifie. L'arcmin
explose a courte portee (0.9m a 15-20m = 188'). port_gellhorn "pire zone"
a 4.2' = 3e MEILLEURE en metres (0.09m). Metro (SE) (B), preneur d'otages
#1 du tension-audit, est calibree a 0.046m.
"""
import json, sys

PAYLOAD_B64 = ""

import base64
P = json.loads(base64.b64decode(PAYLOAD_B64))

def patch(path, fn):
    src = open(path).read()
    out, msg = fn(src)
    if out is None:
        print(f'ok  {path}: {msg}')
        return
    open(path, 'w').write(out)
    print(f'EDIT {path}: {msg}')

def f_common(src):
    if 'DUAL-METRIC-V1' in src:
        return None, 'deja migre'
    a = 'def ray_ls_point(rays):'
    assert a in src, 'ancre ray_ls_point introuvable'
    src = src.replace(a, P['common_block'] + a, 1)
    assert P['ff_old_sig'] in src and P['ff_old_body'] in src, 'find_fossils a change'
    src = src.replace(P['ff_old_sig'], P['ff_new_sig'], 1)
    src = src.replace(P['ff_old_body'], P['ff_new_body'], 1)
    return src, 'dual helpers + find_fossils dual'

def f_snap(src):
    if 'median_m' in src:
        return None, 'deja migre'
    return P['snap_full'], 'remplace (version duale complete)'

def f_tiers(src):
    if 'DUAL-METRIC' in src:
        return None, 'deja migre'
    assert P['t_anchor'] in src, 'ancre two_pass/Summary introuvable'
    src = src.replace(P['t_anchor'], P['t_block'], 1)
    return src, 'annotation median_res_m + rapport promotion'

def f_ci(src):
    if 'global_median_m' in src:
        return None, 'deja migre'
    for old, new in P['ci_pairs']:
        assert old in src, 'bloc CI introuvable: ' + old[:60]
        src = src.replace(old, new, 1)
    return src, 'print dual + baseline metres tolerante'

patch('tools/common.py', f_common)
patch('tools/audit/rms_snapshot.py', f_snap)
patch('tools/compute_confidence_tiers.py', f_tiers)
patch('tools/ci_healthcheck.py', f_ci)
print('\nDUAL-METRIC-V1 Phase 1 en place. Valider: rms_snapshot --tag dual, tiers, ci_healthcheck.')
